// ================================================================
// PARSE CALLBACK ONLY
// WF-DHCP-CALLBACK chi xu ly callback_query
// Message text (/report, chat thuong...) -> BO QUA
// ================================================================

const s = $getWorkflowStaticData('global');
const res = Array.isArray($json.result) ? $json.result : [];

if (res.length === 0) {
  return [];
}

const callbacks = [];

for (const u of res) {

  // Khong phai callback -> bo qua
  const cq = u.callback_query;

  if (!cq || !cq.data) {
    continue;
  }

  const data = String(cq.data).trim();
  const separator = data.indexOf('|');

  const action = (
    separator >= 0
      ? data.slice(0, separator)
      : data
  ).trim().toLowerCase();

  const mac = (
    separator >= 0
      ? data.slice(separator + 1)
      : ''
  ).trim().toLowerCase();

  // Chi chap nhan APPROVE / REJECT
  if (!['approve', 'reject'].includes(action)) {
    continue;
  }

  if (!mac) {
    continue;
  }

  callbacks.push({
    update_id: Number(u.update_id || 0),

    action,
    mac,

    callback_query_id: cq.id,

    chat_id:
      cq.message?.chat?.id || null,

    message_id:
      cq.message?.message_id || null,

    by:
      cq.from?.username ||
      cq.from?.first_name ||
      'admin'
  });
}

// Khong co callback hop le -> dung workflow
if (callbacks.length === 0) {
  return [];
}

// Sap xep de xu ly dung thu tu
callbacks.sort(
  (a, b) => a.update_id - b.update_id
);

// Cap nhat callback offset
const maxCallbackUpdateId =
  Math.max(...callbacks.map(x => x.update_id));

s.tg_offset = maxCallbackUpdateId + 1;

return callbacks.map(c => ({
  json: c
}));

// APPROVE: chon IP trong dai 192.168.12.11 - 192.168.12.199 (bo cac IP da cap),
// tra hostname tu pending, chuan bi dong ghi approved_macs.txt + text sua tin nhan.
const approvedTxt = $('Extract Approved (cb)').first()?.json?.data || '';
const pendingTxt  = $('Extract Pending (cb)').first()?.json?.data || '';
const info = $('Parse Callback').first().json;
const mac  = info.mac;

// IP da su dung
const used = new Set();
for (const l of approvedTxt.split('\n')) {
  const p = l.split(',');
  if (p[1] && p[1].trim()) used.add(p[1].trim());
}
// chon IP trong dau tien
let ip = null;
for (let i = 11; i <= 199; i++) {
  const cand = '192.168.12.' + i;
  if (!used.has(cand)) { ip = cand; break; }
}
// hostname tu pending
let hostname = '';
for (const l of pendingTxt.split('\n')) {
  const p = l.split(',');
  if ((p[0] || '').trim().toLowerCase() === mac) { hostname = (p[1] || '').trim(); break; }
}

if (!ip) {
  return [{ json: { ...info, hostname, ip: null,
    edit_text: '\u26A0\uFE0F KHONG THE APPROVE ' + mac + '\nHet IP trong trong dai 12.11-12.199.' }}];
}
return [{ json: {
  ...info, ip, hostname,
  approved_line: mac + ',' + ip + ',' + hostname + '\n',
  edit_text: '\u2705 APPROVED\nMAC: ' + mac + '\nIP: ' + ip +
             '\nHostname: ' + (hostname || '') + '\nAdmin: ' + info.by
}}];

// REJECT: chuan bi dong ghi rejected_macs.txt + text sua tin nhan.
const info = $('Parse Callback').first().json;
const mac = info.mac;
return [{ json: {
  ...info,
  reject_line: mac + '\n',
  edit_text: '\u26D4 REJECTED\nMAC: ' + mac + '\nThiết bị sẽ bị chặn cấp IP.\nBoi: ' + info.by
}}];

const s = $getWorkflowStaticData('global');
s.tg_offset = s.tg_offset || 0;
return [{ json: { offset: s.tg_offset } }];

// ================================================================
// RESOLVE PENDING DEVICE
// Tim thong tin MAC + hostname trong pending_macs.txt
// dua tren MAC nhan duoc tu Telegram callback
// ================================================================

// Du lieu tu Parse Callback
const callback = $('Parse Callback').first()?.json || {};

// Du lieu file pending
const pendingTxt =
  $('Extract Pending (cb)').first()?.json?.data || '';

// ------------------------------------------------
// Lay action va MAC tu Parse Callback
// ------------------------------------------------

let action = String(callback.action || '').trim().toLowerCase();
let callbackMac = String(callback.mac || '').trim().toLowerCase();

// Ho tro truong hop Parse Callback chi tra callback_data
const callbackData =
  callback.callback_data ||
  callback.data ||
  callback.callback_query?.data ||
  '';

if ((!action || !callbackMac) && callbackData) {
  const parts = String(callbackData).split('|');

  action = action || String(parts[0] || '').trim().toLowerCase();
  callbackMac =
    callbackMac ||
    String(parts[1] || '').trim().toLowerCase();
}

// ------------------------------------------------
// Chuan hoa MAC
// ------------------------------------------------

const normalizeMac = value =>
  String(value || '')
    .trim()
    .toLowerCase();

// Kiem tra MAC
const MAC_REGEX =
  /^[0-9a-f]{2}(?::[0-9a-f]{2}){5}$/i;

callbackMac = normalizeMac(callbackMac);

if (!MAC_REGEX.test(callbackMac)) {
  throw new Error(
    `MAC callback không hợp lệ: "${callbackMac}"`
  );
}

// ------------------------------------------------
// Parse pending_macs.txt
//
// Ho tro:
// mac
// mac,hostname
// ------------------------------------------------

const pendingDevices = pendingTxt
  .split(/\r?\n/)
  .map(line => line.trim())
  .filter(Boolean)
  .map(line => {
    const columns = line.split(',');

    const mac = normalizeMac(columns.shift());
    const hostname = columns.join(',').trim();

    return {
      raw_line: line,
      mac,
      hostname,
    };
  });

// ------------------------------------------------
// Tim MAC trong pending
// ------------------------------------------------

const device = pendingDevices.find(
  item => item.mac === callbackMac
);

if (!device) {
  throw new Error(
    `Không tìm thấy MAC ${callbackMac} trong pending_macs.txt`
  );
}

// ------------------------------------------------
// Output cho cac node phia sau
// ------------------------------------------------

return [
  {
    json: {
      ...callback,

      action,
      mac: device.mac,
      hostname: device.hostname,

      // Gia tri dung de gui Ansible
      ansible_mac: device.mac,
      ansible_hostname: device.hostname,

      // Dong pending goc
      pending_line: device.raw_line,

      // Debug
      found_in_pending: true,
    },
  },
];

