// ================================================================
// FIND DHCPACK BY MAC
// Tim IP thuc te duoc pfSense xac nhan cho MAC vua APPROVE
// ================================================================

const log =
  $('Extract DHCP (verify)').first()?.json?.data || '';

const device =
  $('Resolve Pending Device').first()?.json || {};

const mac = String(device.mac || '')
  .trim()
  .toLowerCase();

const approvalStartedAt =
  Date.parse(device.approval_started_at || '');

if (!/^[0-9a-f]{2}(?::[0-9a-f]{2}){5}$/i.test(mac)) {
  throw new Error(`MAC không hợp lệ: "${mac}"`);
}

const escapedMac = mac.replace(
  /[.*+?^${}()|[\]\\]/g,
  '\\$&'
);

// Vi du:
// DHCPACK on 192.168.12.200 to 00:0c:29:49:fb:b4 (DESKTOP-D24DCNT) via em3
const ackRegex = new RegExp(
  '\\bDHCPACK\\s+on\\s+' +
  '(\\d{1,3}(?:\\.\\d{1,3}){3})' +
  '\\s+to\\s+' +
  escapedMac +
  '(?:\\s+\\(([^)]+)\\))?',
  'i'
);

const lines = log.split(/\r?\n/);

let assignedIp = '';
let hostname = String(device.hostname || '').trim();
let ackLine = '';
let ackTimestamp = '';

// Doc tu cuoi log len de lay DHCPACK moi nhat
for (let index = lines.length - 1; index >= 0; index--) {
  const line = lines[index].trim();

  if (!line) continue;

  const match = line.match(ackRegex);
  if (!match) continue;

  // Neu log co timestamp ISO o dau dong:
  // 2026-07-26T07:07:03.947623+00:00 ...
  const timestampMatch = line.match(
    /^(\d{4}-\d{2}-\d{2}T\S+)/
  );

  if (timestampMatch && Number.isFinite(approvalStartedAt)) {
    const lineTime = Date.parse(timestampMatch[1]);

    // Bo qua DHCPACK cu truoc luc admin bam APPROVE
    if (
      Number.isFinite(lineTime) &&
      lineTime < approvalStartedAt - 2000
    ) {
      continue;
    }

    ackTimestamp = timestampMatch[1];
  }

  assignedIp = String(match[1] || '').trim();

  if (match[2]) {
    hostname = String(match[2]).trim();
  }

  ackLine = line;
  break;
}

// Chua thay DHCPACK moi
if (!assignedIp) {
  return [
    {
      json: {
        ...device,

        verified: false,
        mac,
        hostname,

        telegram_text:
          '⏳ ĐÃ APPROVE THIẾT BỊ\n' +
          'MAC: ' + mac + '\n' +
          'Hostname: ' + (hostname || '') + '\n' +
          'Admin: ' + (device.by || '') + '\n\n' +
          'Ansible đã xử lý nhưng chưa tìm thấy DHCPACK mới từ pfSense.',
      },
    },
  ];
}

// Da thay DHCPACK
return [
  {
    json: {
      ...device,

      verified: true,

      mac,
      ip: assignedIp,
      hostname,

      dhcp_ack_line: ackLine,
      dhcp_ack_timestamp: ackTimestamp,

      telegram_text:
        '✅ APPROVED\n' +
        'MAC: ' + mac + '\n' +
        'IP: ' + assignedIp + '\n' +
        'Hostname: ' + (hostname || '') + '\n' +
        'Admin: ' + (device.by || ''),
    },
  },
];

// ================================================================
// MARK APPROVAL RECEIVED
// Moc n8n nhan callback APPROVE
// ================================================================

const now = Date.now();

return items.map(item => ({
  json: {
    ...item.json,

    approved_at_ms: now,
    approved_at: new Date(now).toISOString()
  }
}));

// ================================================================
// FIND APPROVAL EVENT
// Match MAC hien tai voi DeviceEvent_Approval.jsonl
// ================================================================

const device = $('Resolve Pending Device').item.json;
const approval = $('Mark Approval Received').item.json;

const mac = String(
  device.mac ||
  device.client_mac ||
  ''
).trim().toLowerCase();

if (!mac) {
  throw new Error('Khong tim thay MAC tu Resolve Pending Device');
}

const text =
  $('Extract Approval Event').first()?.json?.data || '';

const events = text
  .split(/\r?\n/)
  .map(s => s.trim())
  .filter(Boolean)
  .map(line => {
    try {
      return JSON.parse(line);
    } catch {
      return null;
    }
  })
  .filter(event =>
    event &&
    String(event.mac || '').toLowerCase() === mac &&
    event.scenario === 'APPROVE_MAC'
  )
  .sort(
    (a, b) =>
      Number(b.process_started_at_ms || 0) -
      Number(a.process_started_at_ms || 0)
  );

const event = events[0] || null;

return [{
  json: {
    ...device,

    scenario: 'APPROVE_MAC',

    metrics_found: Boolean(event),

    event_id:
      event?.event_id || null,

    process_started_at_ms:
      event?.process_started_at_ms || null,

    process_started_at:
      event?.process_started_at || null,

    approved_at_ms:
      approval.approved_at_ms || null,

    approved_at:
      approval.approved_at || null
  }
}];

// ================================================================
// END APPROVAL PROCESSING
// New MAC detected -> DHCPACK verified
// ================================================================

const context = $('Find Approval Event').item.json;

const start = Number(context.process_started_at_ms);
const approved = Number(context.approved_at_ms);
const end = Date.now();

if (!Number.isFinite(start)) {
  throw new Error('Khong tim thay process_started_at_ms');
}

const totalMs = end - start;

return [{
  json: {
    ...context,

    status: 'success',

    processing_finished_at_ms: end,
    processing_finished_at:
      new Date(end).toISOString(),

    // Tong: New MAC detected -> DHCPACK verified
    total_processing_ms: totalMs,

    total_processing_seconds:
      Number((totalMs / 1000).toFixed(3)),

    // Rieng automation: n8n nhan APPROVE -> DHCPACK verified
    automation_after_approval_ms:
      Number.isFinite(approved)
        ? end - approved
        : null,

    automation_after_approval_seconds:
      Number.isFinite(approved)
        ? Number(((end - approved) / 1000).toFixed(3))
        : null
  }
}];

// ================================================================
// PREPARE METRICS - APPROVE_MAC
// ================================================================

const metric = {
  schema_version: 1,

  scenario: 'APPROVE_MAC',
  event_id: $json.event_id || null,

  mac: $json.mac || null,
  hostname: $json.hostname || null,

  ip:
    $json.ip ||
    $json.assigned_ip ||
    null,

  status: $json.status || 'success',

  // START: phat hien thiet bi moi
  process_started_at_ms:
    $json.process_started_at_ms,

  process_started_at:
    $json.process_started_at,

  // n8n nhan APPROVE
  approved_at_ms:
    $json.approved_at_ms,

  approved_at:
    $json.approved_at,

  // END: DHCPACK verified
  processing_finished_at_ms:
    $json.processing_finished_at_ms,

  processing_finished_at:
    $json.processing_finished_at,

  // Tong end-to-end
  total_processing_ms:
    $json.total_processing_ms,

  total_processing_seconds:
    $json.total_processing_seconds,

  // Automation sau approval
  automation_after_approval_ms:
    $json.automation_after_approval_ms,

  automation_after_approval_seconds:
    $json.automation_after_approval_seconds
};

return [{
  json: {
    ...$json,
    metrics_content:
      JSON.stringify(metric) + '\n'
  }
}];
